/**
 * Save field names that are needed for rules
 * @param {*} context
 */
function saveElementsInRules(fieldName) {
  const pattern = new RegExp('\\b(' + fieldName + ')\\b', 'i'); //ig

  if (!Object.prototype.hasOwnProperty.call(fieldsInVisibilityRules, fieldName)) {
    //Already found this field in a rule
    for (const control in fsmFormInstance.visibilityRules) {
      //Loop over all visibility rules
      if (fsmFormInstance.visibilityRules[control].Rule.match(pattern)) {
        //Does this field exist in visibilty rule criteria?
        fieldsInVisibilityRules[fieldName] = true;
        return;
      }
    }
  }
}

/**
 * Save field names that are needed for calculations
 * @param {*} context
 */
function saveElementsInCalculations(fieldName) {
  const pattern = new RegExp('\\b(' + fieldName + ')\\b', 'i'); //ig

  if (!Object.prototype.hasOwnProperty.call(fieldsInCalculations, fieldName)) {
    //Already found this field in a calculation
    for (const control in fsmFormInstance.calculationRules) {
      //Loop over all calculations
      if (fsmFormInstance.calculationRules[control].Rule.match(pattern)) {
        //Does this field exist in calculation rule criteria?
        fieldsInCalculations[fieldName] = true;
        return;
      }
    }
  }
}

/**
 * Helper function to determine action type of attachment allowed based on allowedTypes
 * @param {*} allowedTypes
 */
function attachmentPickerActionType(allowedTypes) {
  let types = [];
  if ('PNG,TIFF,GIF,JPG,JPEG,TIF,BMP,ICO' === allowedTypes) {
    types.push('AddPhoto');
    types.push('TakePhoto');
  } else if ('MOV,3GP,M4V,MP4' === allowedTypes) {
    types.push('SelectFile');
  } else if ('*' === allowedTypes) {
    types.push('AddPhoto');
    types.push('TakePhoto');
    types.push('SelectFile');
  }
  return types;
}

/**
 * Helper function to determine file type of attachment allowed based on allowedTypes
 * @param {*} allowedTypes
 */
function attachmentPickerFileType(allowedTypes) {
  let types = [];
  if ('PNG,TIFF,GIF,JPG,JPEG,TIF,BMP,ICO' === allowedTypes) {
    types.push('PNG');
    types.push('TIFF');
    types.push('GIF');
    types.push('JPG');
    types.push('JPEG');
    types.push('TIF');
    types.push('BMP');
    types.push('ICO');
  } else if ('MOV,3GP,M4V,MP4' === allowedTypes) {
    types.push('MOV');
    types.push('3GP');
    types.push('M4V');
    types.push('MP4');
  } else if ('*' === allowedTypes) {
    return types;
  }
  return types;
}

